# client.py  -  HORSE CASINO client (2D, 8-bit style)
# Install once:   pip install pygame
# Run it with:    python client.py
#
# No image or sound files needed: horses are drawn with little squares
# and the 8-bit music is generated by the code itself.

import socket
import threading
import json
import time
import sys
import random
from array import array
import pygame

# ---------------------------------------------------------------- settings
SERVER_IP = input("Server IP (just press Enter if the server is on this computer): ").strip() or "127.0.0.1"
TCP_PORT = 5000
UDP_PORT = 5001
TRACK_LENGTH = 1000.0     # must be the same number as in server.py

W, H = 900, 600
HORSE_NAMES = ["Turbo", "Bolt", "Pixel", "Lucky"]
HORSE_COLORS = [(230, 60, 60), (70, 120, 255), (60, 200, 90), (250, 210, 50)]
WHITE, YELLOW, GREEN, RED, CYAN = (255, 255, 255), (255, 220, 60), (80, 255, 120), (255, 80, 80), (80, 230, 255)

# ---------------------------------------------------------------- connect to server
try:
    tcp = socket.socket(socket.AF_INET, socket.SOCK_STREAM)   # TCP: login, rooms, bets, results
    tcp.connect((SERVER_IP, TCP_PORT))
except OSError:
    print("Can't connect to the server. Is server.py running? Is the IP right?")
    sys.exit()
udp = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)        # UDP: horse positions, cheers
send_lock = threading.Lock()

# Everything the screen needs to know lives in this dictionary
S = {"screen": "login",   # login / lobby / room / betting / race / results / final
     "connected": True, "input": "", "name": None, "wins": 0,
     "rooms": [], "room": None, "round": 0, "rounds": 3, "bet_end": 0,
     "pick": 0, "amount": 10, "my_bet": None, "bets": {},
     "pos": [0.0] * 4, "result": None, "final": None,
     "msg": "", "msg_time": 0}


def notify(text):
    """Show a red message at the bottom of the screen for a few seconds."""
    S["msg"] = text
    S["msg_time"] = time.time()


def send_tcp(msg):
    with send_lock:
        try:
            tcp.sendall((json.dumps(msg) + "\n").encode())
        except OSError:
            S["connected"] = False


def send_udp(msg):
    try:
        udp.sendto(json.dumps(msg).encode(), (SERVER_IP, UDP_PORT))
    except OSError:
        pass


# ---------------------------------------------------------------- messages from the server
def handle_message(m):
    t = m["type"]
    if t == "login_ok":
        S["name"], S["wins"], S["screen"] = m["name"], m["wins"], "lobby"
        threading.Thread(target=keepalive, daemon=True).start()
    elif t == "error":
        notify(m["msg"])
    elif t == "rooms":
        S["rooms"] = m["rooms"]
    elif t == "room_update":
        S["room"] = m
        if S["screen"] == "lobby":          # we just created / joined a room
            S["screen"] = "room"
    elif t == "left_room":
        S["room"], S["screen"] = None, "lobby"
    elif t == "player_left":
        notify(m["name"] + " left the game")
    elif t == "betting":                    # a new round starts: betting time
        S.update(screen="betting", round=m["round"], rounds=m["rounds"],
                 bet_end=time.time() + m["seconds"], my_bet=None,
                 amount=10, pos=[0.0] * 4, result=None)
    elif t == "bet_ok":
        S["my_bet"] = (m["horse"], m["amount"])
    elif t == "race_start":                 # the horses run!
        S["bets"] = m["bets"]
        S["pos"] = [0.0] * 4
        S["screen"] = "race"
    elif t == "race_end":
        S["pos"], S["result"], S["screen"] = m["pos"], m, "results"
    elif t == "game_end":
        S["final"], S["screen"] = m, "final"
        S["wins"] = m["wins"].get(S["name"], S["wins"])


def tcp_listener():
    """Thread: reads lines from the server forever."""
    buf = ""
    try:
        while True:
            data = tcp.recv(4096)
            if not data:
                break
            buf += data.decode()
            while "\n" in buf:              # one message per line
                line, buf = buf.split("\n", 1)
                if line.strip():
                    handle_message(json.loads(line))
    except OSError:
        pass
    S["connected"] = False                  # server is gone


def udp_listener():
    """Thread: receives the horse positions (UDP)."""
    while True:
        try:
            data, _ = udp.recvfrom(1024)
            m = json.loads(data.decode())
            if m["type"] == "pos":
                S["pos"] = m["pos"]         # newest position wins, lost packets don't matter
        except Exception:
            time.sleep(0.05)


def keepalive():
    """Thread: every 2 seconds tell the server 'I'm alive' (TCP) and 'my UDP address is this' (UDP)."""
    while S["connected"]:
        send_udp({"type": "hello", "name": S["name"]})
        send_tcp({"type": "ping"})
        time.sleep(2)


# ---------------------------------------------------------------- 8-bit music (made by code)
RATE = 22050
pygame.mixer.pre_init(RATE, -16, 1, 512)    # 22050 Hz, 16 bit, mono
pygame.init()


def make_tune(notes, note_len, volume, shape):
    """Turn a list of note frequencies into a sound. 0 = silence."""
    samples = array("h")
    n = int(RATE * note_len)                # samples per note
    for freq in notes:
        for i in range(n):
            if freq == 0:
                samples.append(0)
                continue
            phase = (i / RATE * freq) % 1   # 0..1 position inside one wave
            if shape == "square":           # harsh 8-bit sound
                wave = 1 if phase < 0.5 else -1
            else:                           # triangle = softer, calmer sound
                wave = 4 * abs(phase - 0.5) - 1
            fade = 1 - 0.6 * i / n          # little fade so notes sound separate
            samples.append(int(wave * fade * volume * 32767))
    return pygame.mixer.Sound(buffer=samples.tobytes())


C4, D4, E4, G4, A4, B4 = 262, 294, 330, 392, 440, 494
C5, D5, Eb5, E5, F5, G5 = 523, 587, 622, 659, 698, 784

tunes = {}
try:
    # CALM: slow, soft, happy notes (lobby + betting)
    tunes["calm"] = make_tune([C4, E4, G4, E4, A4, G4, E4, D4,
                               C4, E4, G4, C5, A4, G4, E4, D4], 0.35, 0.25, "triangle")
    # CHAOS: fast, harsh, scary notes (during the race)
    tunes["chaos"] = make_tune([A4, A4, C5, A4, E5, A4, C5, A4, A4, A4, D5, A4, F5, A4, D5, A4,
                                G5, E5, C5, E5, G5, E5, C5, E5, B4, D5, F5, D5, Eb5, D5, B4, D5],
                               0.11, 0.2, "square")
except pygame.error:
    print("No sound device found, playing without music.")

current_music = None


def play_music(name):
    """Switch to another tune (only if it's not already playing)."""
    global current_music
    if name == current_music or name not in tunes:
        return
    pygame.mixer.stop()
    tunes[name].play(loops=-1)              # -1 = repeat forever
    current_music = name


# ---------------------------------------------------------------- drawing (pixel art)
screen = pygame.display.set_mode((W, H))
pygame.display.set_caption("HORSE CASINO")
clock = pygame.time.Clock()
fonts = {}
stars = [(random.randint(0, W), random.randint(0, H)) for _ in range(50)]

# Each X is one big pixel. E is the eye.
HORSE_BODY = ["...........XX..",
              "..........XXEX.",
              "..XXXXXXXXXXXX.",
              ".XXXXXXXXXXXXX.",
              "XXXXXXXXXXXXX..",
              ".XXXXXXXXXXXX.."]
LEGS = [["..X.X....X.X...", "..X.X....X.X...", "..X.X....X.X..."],   # legs frame 1
        ["...XX...XX.....", ".XX..XX.X..X...", "X......X....X.."]]   # legs frame 2
P = 4   # size of one pixel


def draw_text(text, x, y, size=28, color=WHITE, center=False):
    if size not in fonts:
        fonts[size] = pygame.font.SysFont("couriernew", size, bold=True)
    img = fonts[size].render(str(text), False, color)    # False = no smoothing = pixelated
    if center:
        x -= img.get_width() // 2
    screen.blit(img, (x, y))


def draw_horse(x, y, color, frame):
    dark = (color[0] // 2, color[1] // 2, color[2] // 2)
    for r, row in enumerate(HORSE_BODY):
        for c, ch in enumerate(row):
            if ch != ".":
                col = WHITE if ch == "E" else color
                pygame.draw.rect(screen, col, (x + c * P, y + r * P, P, P))
    for r, row in enumerate(LEGS[frame]):
        for c, ch in enumerate(row):
            if ch == "X":
                pygame.draw.rect(screen, dark, (x + c * P, y + (6 + r) * P, P, P))


def draw_login():
    draw_text("HORSE CASINO", W // 2, 100, 72, YELLOW, True)
    draw_text("Type your name and press ENTER", W // 2, 230, 30, WHITE, True)
    cursor = "_" if int(time.time() * 2) % 2 else " "
    draw_text(S["input"] + cursor, W // 2, 290, 44, GREEN, True)
    draw_horse(W // 2 - 30, 400, YELLOW, int(time.time() * 6) % 2)


def draw_lobby():
    draw_text("Player: %s    Wins: %d" % (S["name"], S["wins"]), 40, 90, 28, GREEN)
    draw_text("ROOMS  (press the number to join)", 40, 140, 28, WHITE)
    if not S["rooms"]:
        draw_text("No rooms yet.", 60, 190, 26, CYAN)
    for i, r in enumerate(S["rooms"][:9]):
        draw_text("%d. %s  (%d/4)  %s" % (i + 1, r["name"], r["count"], r["state"]),
                  60, 185 + i * 34, 26, CYAN)
    draw_text("C = create a room", 40, 520, 28, YELLOW)


def draw_room():
    room = S["room"]
    if not room:
        return
    draw_text("ROOM: " + room["name"], 40, 90, 34, YELLOW)
    for i, m in enumerate(room["members"]):
        draw_text(m + ("  (host)" if m == room["host"] else ""), 60, 160 + i * 40, 30, WHITE)
    draw_text("S = start game (host only, 2-4 players)", 40, 440, 26, GREEN)
    draw_text("L = leave room", 40, 480, 26, RED)


def draw_betting():
    room = S["room"] or {}
    chips = room.get("chips", {}).get(S["name"], 0)
    left = max(0, int(S["bet_end"] - time.time()))
    draw_text("ROUND %d/%d     Time left: %ds" % (S["round"], S["rounds"], left), 40, 80, 32, YELLOW)
    draw_text("Your chips: %d" % chips, 40, 120, 30, GREEN)
    for i in range(4):
        y = 170 + i * 66
        if S["pick"] == i:
            pygame.draw.rect(screen, WHITE, (60, y - 8, 420, 52), 3)   # frame around chosen horse
        draw_horse(80, y, HORSE_COLORS[i], 0)
        draw_text("%d. %s" % (i + 1, HORSE_NAMES[i]), 200, y + 6, 30, HORSE_COLORS[i])
    if S["my_bet"]:
        h, a = S["my_bet"]
        draw_text("BET PLACED: %d on %s. Waiting for the others..." % (a, HORSE_NAMES[h]), 40, 450, 26, GREEN)
    else:
        draw_text("Bet: %d chips   (UP/DOWN = amount)" % S["amount"], 40, 450, 26, WHITE)
        draw_text("1-4 = pick horse    ENTER = place bet", 40, 485, 26, WHITE)
    draw_text("Already bet: " + ", ".join(room.get("bet_names", [])), 40, 530, 24, CYAN)


def draw_race():
    draw_text("GO GO GO!   MASH SPACE TO PUSH YOUR HORSE!", W // 2, 20, 30, YELLOW, True)
    start_x, finish_x = 20, W - 90
    frame = int(time.time() * 8) % 2                       # makes the legs move
    my_horse = S["bets"].get(S["name"], [None])[0]
    for i in range(4):
        top = 70 + i * 85
        pygame.draw.rect(screen, (40, 110, 50) if i % 2 == 0 else (50, 130, 60), (0, top, W, 85))
        x = start_x + S["pos"][i] / TRACK_LENGTH * (finish_x - start_x - 60)
        draw_horse(x, top + 25, HORSE_COLORS[i], frame)
        if i == my_horse:
            draw_text("YOU", x + 15, top + 2, 24, WHITE)
    for k in range(0, 4 * 85, 12):                          # finish line (checkers)
        pygame.draw.rect(screen, WHITE if (k // 12) % 2 == 0 else (0, 0, 0), (finish_x, 70 + k, 12, 12))
    y = 425
    for name, (h, a) in S["bets"].items():
        draw_text("%s bet %d on %s" % (name, a, HORSE_NAMES[h]), 40, y, 24, HORSE_COLORS[h])
        y += 30


def draw_results():
    r = S["result"]
    if not r:
        return
    w = r["winner"]
    draw_text("RACE OVER!", W // 2, 70, 60, YELLOW, True)
    draw_horse(W // 2 - 30, 150, HORSE_COLORS[w], int(time.time() * 6) % 2)
    draw_text("Winner: " + HORSE_NAMES[w], W // 2, 210, 36, HORSE_COLORS[w], True)
    y = 280
    for name, chips in r["chips"].items():
        d = r["payouts"].get(name, 0)
        draw_text("%s   %+d   (chips: %d)" % (name, d, chips), W // 2, y, 30,
                  GREEN if d > 0 else RED if d < 0 else WHITE, True)
        y += 45
    draw_text("Next round coming...", W // 2, 520, 24, CYAN, True)


def draw_final():
    f = S["final"]
    if not f:
        return
    draw_text("GAME OVER", W // 2, 70, 60, YELLOW, True)
    draw_text("WINNER: " + " & ".join(f["winners"]), W // 2, 150, 40, GREEN, True)
    for i, (name, chips) in enumerate(f["ranking"]):
        draw_text("%d. %s - %d chips" % (i + 1, name, chips), W // 2, 230 + i * 45, 32, WHITE, True)
    draw_text("Press ENTER to go back to the room", W // 2, 500, 26, CYAN, True)


# ---------------------------------------------------------------- keyboard
def handle_key(event):
    scr = S["screen"]
    key = event.key
    if scr == "login":
        if key == pygame.K_RETURN and S["input"].strip():
            send_tcp({"type": "login", "name": S["input"].strip()})
        elif key == pygame.K_BACKSPACE:
            S["input"] = S["input"][:-1]
        elif event.unicode.isprintable() and event.unicode and len(S["input"]) < 12:
            S["input"] += event.unicode

    elif scr == "lobby":
        if key == pygame.K_c:
            send_tcp({"type": "create_room", "room": "Room-" + S["name"]})
        elif pygame.K_1 <= key <= pygame.K_9:
            i = key - pygame.K_1
            if i < len(S["rooms"]):
                send_tcp({"type": "join_room", "room": S["rooms"][i]["name"]})

    elif scr == "room":
        if key == pygame.K_s:
            send_tcp({"type": "start_game"})
        elif key == pygame.K_l:
            send_tcp({"type": "leave_room"})

    elif scr == "betting" and not S["my_bet"]:
        chips = (S["room"] or {}).get("chips", {}).get(S["name"], 0)
        if pygame.K_1 <= key <= pygame.K_4:
            S["pick"] = key - pygame.K_1
        elif key == pygame.K_UP:
            S["amount"] = min(max(10, chips), S["amount"] + 10)
        elif key == pygame.K_DOWN:
            S["amount"] = max(10, S["amount"] - 10)
        elif key == pygame.K_RETURN:
            send_tcp({"type": "bet", "horse": S["pick"], "amount": S["amount"]})

    elif scr == "race":
        if key == pygame.K_SPACE:
            send_udp({"type": "cheer", "name": S["name"]})   # UDP: fast, no need to be reliable

    elif scr == "final":
        if key == pygame.K_RETURN:
            S["screen"] = "room" if S["room"] else "lobby"


# ---------------------------------------------------------------- main loop
threading.Thread(target=tcp_listener, daemon=True).start()
threading.Thread(target=udp_listener, daemon=True).start()

screens = {"login": draw_login, "lobby": draw_lobby, "room": draw_room,
           "betting": draw_betting, "race": draw_race,
           "results": draw_results, "final": draw_final}

while True:
    for event in pygame.event.get():
        if event.type == pygame.QUIT:
            pygame.quit()
            sys.exit()                      # closing the window closes the sockets = server sees a disconnect
        if event.type == pygame.KEYDOWN:
            handle_key(event)

    play_music("chaos" if S["screen"] == "race" else "calm")

    screen.fill((18, 10, 40))
    for sx, sy in stars:
        pygame.draw.rect(screen, (90, 80, 140), (sx, sy, 3, 3))
    if S["screen"] not in ("login", "race"):
        draw_text("HORSE CASINO", 40, 20, 44, YELLOW)
    screens[S["screen"]]()

    if not S["connected"]:
        draw_text("CONNECTION LOST - close the window", W // 2, H - 70, 30, RED, True)
    elif time.time() - S["msg_time"] < 4:
        draw_text(S["msg"], W // 2, H - 35, 26, RED, True)

    pygame.display.flip()
    clock.tick(30)
